"""Loader for the stop list generated by the stop list script."""

import csv
import logging
from pathlib import Path

from custom_components.vienna_transport.stop_list import StopListEntry

_LOGGER = logging.getLogger(__name__)

_DEFAULT_PATH = Path(__file__).parent / "data" / "stops.csv"
_ENCODING = "utf-8"
_DELIMITER = ";"


class StopListLoader:
    """Loader for the stop list shipped with the integration.

    The stop list lists each line departing from each stop in each direction.
    It is only needed while setting up stops, so it is read from disk on
    demand and not kept by the loader.
    """

    def __init__(self, path: Path = _DEFAULT_PATH) -> None:
        """Initialize loader.

        Args:
            path: Path of the stop list.

        """
        self._path = path

    def load(self) -> list[StopListEntry]:
        """Load the stop list.

        Reads from disk, so call it from an executor job.

        Returns:
            Entries in file order.

        Raises:
            FileNotFoundError: If there is no stop list at the path.

        """
        try:
            with self._path.open(encoding=_ENCODING, newline="") as file:
                entries = [
                    StopListEntry(
                        stop_id=int(row["stop_id"]),
                        name=row["name"],
                        line=row["line"],
                        towards=row["towards"],
                    )
                    for row in csv.DictReader(file, delimiter=_DELIMITER)
                ]
        except FileNotFoundError:
            _LOGGER.warning("Stop list not found at %s", self._path)
            raise

        _LOGGER.debug("Loaded %d stop list entries from %s", len(entries), self._path)
        return entries
